#!/bin/sh
# `sv verify-auto` on the full csrng IP (lowRISC/opentitan 558921ccc); run in mununu-sva, cwd = this dir.
# Extraction reads the real prim_assert macros; the lift sees the synthesis shim (assertions compiled
# out, INC_ASSERT defined) and, for each `--strip-inc-assert` file, its `_lift.sv` variant.
# Add `--source mununu_properties.sv` for the system-level @mununu_guarantee properties.
exec mununu sv verify-auto csrng.sv --top csrng --preprocess-sv2v --source aes_reg_pkg.sv --source prim_util_pkg.sv --source aes_pkg.sv --source csrng_reg_pkg.sv --source entropy_src_pkg.sv --source csrng_pkg.sv --source edn_pkg.sv --source lc_ctrl_reg_pkg.sv --source lc_ctrl_state_pkg.sv --source prim_mubi_pkg.sv --source lc_ctrl_pkg.sv --source prim_alert_pkg.sv --source prim_count_pkg.sv --source prim_secded_pkg.sv --source prim_subreg_pkg.sv --source top_pkg.sv --source tlul_pkg.sv --source prim_assert.sv --source prim_assert_sec_cm.svh --source prim_assert_standard_macros.svh --source prim_flop_macros.sv --source prim_assert_dummy_macros.svh --source prim_assert_yosys_macros.svh --source prim_fifo_assert.svh --source aes_cipher_core_bbox.sv --source csrng_block_encrypt.sv --source csrng_cmd_stage.sv --source csrng_core.sv --source csrng_ctr_drbg.sv --source csrng_main_sm.sv --source csrng_reg_top.sv --source csrng_state_db.sv --source prim_alert_sender.sv --source prim_arbiter_ppc.sv --source prim_buf.sv --source prim_count.sv --source prim_diff_decode.sv --source prim_edge_detector.sv --source prim_fifo_sync.sv --source prim_fifo_sync_cnt.sv --source prim_flop.sv --source prim_flop_2sync.sv --source prim_intr_hw.sv --source prim_lc_sync.sv --source prim_leading_one_ppc.sv --source prim_mubi4_sync.sv --source prim_mubi8_sync.sv --source prim_onehot_check.sv --source prim_packer_fifo.sv --source prim_reg_we_check.sv --source prim_sec_anchor_buf.sv --source prim_sec_anchor_flop.sv --source prim_secded_inv_39_32_dec.sv --source prim_secded_inv_39_32_enc.sv --source prim_secded_inv_64_57_dec.sv --source prim_secded_inv_64_57_enc.sv --source prim_sparse_fsm_flop.sv --source prim_subreg.sv --source prim_subreg_arb.sv --source prim_subreg_ext.sv --source tlul_adapter_reg.sv --source tlul_cmd_intg_chk.sv --source tlul_data_integ_dec.sv --source tlul_data_integ_enc.sv --source tlul_err.sv --source tlul_rsp_intg_gen.sv \
  --lift-override prim_assert.sv=prim_assert_shim.sv \
  --lift-override prim_assert_standard_macros.svh=/dev/null \
  --lift-override prim_assert_sec_cm.svh=/dev/null \
  --lift-override prim_alert_sender.sv=prim_alert_sender_lift.sv \
  --lift-override prim_sparse_fsm_flop.sv=prim_sparse_fsm_flop_lift.sv \
  --pin rst_ni=1 "$@"
